import { Tag } from '@aws-sdk/client-ec2';
import { randomUUID } from 'crypto';
import EventEmitter from 'events';
import { AuditService } from '../../audit/audit.service';
import { AuditScope } from '../../audit/entities/audit.interface';
import { InfluxService } from '../../influx/influx.service';
import { putDocument } from '../../utils/aws/s3';
import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();
export class StandardMeasurementEntity implements MeasurementFormat {
    public timeStamp?: string;
    public dimensionId?: string;
    public businessID: string;
    public applicationId?: string;
    public serviceId?: string;
    public recordValue: number;
    public metadata: Record<string, string>;
    public _measurement: string;
    public static allowedTags = ['paigoApplicationId', 'paigoServiceId', 'paigoDimensionId'];

    constructor(measurement: MeasurementFormat) {
        if (measurement.timeStamp) {
            this.timeStamp = measurement.timeStamp;
        } else {
            this.timeStamp = new Date().toISOString();
        }
        this.dimensionId = measurement.dimensionId;
        this.applicationId = measurement.applicationId;
        this.serviceId = measurement.serviceId;
        this.recordValue = measurement.recordValue;
        this.metadata = measurement.metadata;
        this.businessID = measurement.businessID;
        this._measurement = measurement._measurement;
    }
    static publish(publishRequest: MeasurementFormat) {
        eventEmitter.emit('standardMeasurements', publishRequest);
        return {
            message: 'published',
            id: randomUUID(),
            data: [publishRequest],
        };
    }
    static subscribe(influxService: InfluxService) {
        eventEmitter.on('standardMeasurements', async (measurementFormat: MeasurementFormat) => {
            const point = MeasurementFormat.getPointForm(measurementFormat, influxService);
            try {
                await influxService.loadPoints(`${process.env.STAGE}-usage-data`, `paigo`, [point]);
            } catch (err) {
                AuditService.publishEvent({
                    data: [{ err }],
                    message: 'Failed to index Measurement',
                    topic: AuditScope.ERROR,
                });
            }
        });
    }
    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }

    /**
     * Normalize an S3 object key to a bucket-relative path.
     * Accepts s3://bucket/key, /key, or already-relative keys.
     */
    static normalizeSourceKey(s3Key: string): string {
        if (!s3Key) {
            return s3Key;
        }
        let key = s3Key;
        if (key.startsWith('s3://')) {
            const withoutProtocol = key.slice('s3://'.length);
            const firstSlash = withoutProtocol.indexOf('/');
            key = firstSlash >= 0 ? withoutProtocol.slice(firstSlash + 1) : '';
        }
        if (key.startsWith('/')) {
            key = key.slice(1);
        }
        return key;
    }

    static async publishFailureToDLQ({
        message,
        s3Key,
        error,
        metadata,
    }: {
        message: unknown;
        s3Key?: string;
        error?: unknown;
        metadata?: Record<string, unknown>;
    }) {
        const relativeKey = StandardMeasurementEntity.normalizeSourceKey(s3Key || `unknown/${randomUUID()}`);
        const dlqKey = `${relativeKey}.message.text`;
        const failedAt = new Date().toISOString();
        const errorMessage =
            error instanceof Error
                ? error.message
                : typeof error === 'string'
                ? error
                : error
                ? JSON.stringify(error)
                : 'Unknown error';
        const body = JSON.stringify({
            message,
            s3Key,
            relativeKey,
            error: errorMessage,
            failedAt,
            ...(metadata || {}),
        });
        await putDocument(body, process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME, dlqKey).done();
        return { message: 'Published failure to DLQ', key: dlqKey };
    }
}

